const $ = (id) => document.getElementById(id);
const FORMAT_LABEL = { O: "Open-ended", M: "Multiple-choice" };
let version = "O1", currentIndex = 0, candidate = "", responses = {}, latest = null, stage = "setup";

// Progress is kept in this browser (localStorage) until the candidate returns to the start page.
const STORE_KEY = "iics-assessment-state-v2";
function persist(){
  if(stage === "setup") return;
  const data = JSON.stringify({ stage, candidate, version, currentIndex, responses, latest });
  try{ localStorage.setItem(STORE_KEY, data); }catch{}
  try{ sessionStorage.setItem(STORE_KEY, data); }catch{}
}
function clearSaved(){ try{ localStorage.removeItem(STORE_KEY); }catch{} try{ sessionStorage.removeItem(STORE_KEY); }catch{} }

const fmt = () => version[0];
const num = () => version.slice(1);
const vLabel = () => `${FORMAT_LABEL[fmt()]} · Version ${num()}`;
const safe = (s) => s.replace(/[^a-z0-9_-]+/gi, "_");
const toTop = () => window.scrollTo({ top: 0, behavior: "smooth" });

function isAnswered(i){
  const v = responses[`${version}-${i}`];
  return fmt() === "O" ? typeof v === "string" && v.trim() !== "" : v !== undefined;
}
function updateNav(){
  const nav = $("qNav");
  if(nav.children.length !== 20){
    nav.replaceChildren();
    for(let i = 0; i < 20; i++){
      const b = document.createElement("button");
      b.type = "button"; b.textContent = i + 1;
      b.addEventListener("click", () => { currentIndex = i; render(); toTop(); });
      nav.appendChild(b);
    }
  }
  [...nav.children].forEach((b, i) => {
    const done = isAnswered(i);
    b.classList.toggle("current", i === currentIndex);
    b.classList.toggle("answered", done);
    b.setAttribute("aria-label", `Question ${i + 1}${done ? ", answered" : ", not answered"}`);
    if(i === currentIndex) b.setAttribute("aria-current", "step"); else b.removeAttribute("aria-current");
  });
}

function render(){
  const item = QUESTION_BANK[num()][currentIndex];
  const open = fmt() === "O";
  $("candidateLabel").textContent = `${candidate} · ${vLabel().toUpperCase()}`;
  $("partTitle").textContent = open ? "Open-ended questions" : "Multiple-choice questions";
  $("progressText").textContent = `Question ${currentIndex + 1} of 20`;
  $("progressBar").style.width = `${(currentIndex + 1) * 5}%`;
  const card = document.createElement("article");
  card.className = "question-card";
  const meta = document.createElement("div");
  meta.className = "question-meta";
  meta.innerHTML = `<span class="q-number">QUESTION ${currentIndex + 1} OF 20</span><span class="level"></span><span class="level"></span>`;
  meta.children[1].textContent = item.level; meta.children[2].textContent = item.topic;
  const q = document.createElement("p");
  q.className = "question-text"; q.textContent = open ? item.open : item.mcq;
  card.append(meta, q);
  const key = `${version}-${currentIndex}`;
  if(open){
    const area = document.createElement("textarea");
    area.placeholder = "Write your answer here…"; area.value = responses[key] || "";
    area.addEventListener("input", () => { responses[key] = area.value; persist(); updateNav(); });
    card.appendChild(area);
  } else {
    item.options.forEach((option, i) => {
      const label = document.createElement("label"); label.className = "choice";
      const radio = document.createElement("input");
      radio.type = "radio"; radio.name = "mcq"; radio.checked = responses[key] === i;
      radio.addEventListener("change", () => { responses[key] = i; persist(); updateNav(); });
      const span = document.createElement("span");
      span.textContent = `${String.fromCharCode(65 + i)}. ${option}`;
      label.append(radio, span); card.appendChild(label);
    });
  }
  $("questionList").replaceChildren(card);
  $("backBtn").hidden = currentIndex === 0;
  $("backBtn").textContent = "Previous question";
  $("nextBtn").textContent = currentIndex === 19 ? "Submit assessment" : "Next question";
  updateNav();
  persist();
}

function begin(){
  candidate = $("candidateName").value.trim();
  if(!candidate){ alert("Please enter the candidate name."); $("candidateName").focus(); return; }
  version = $("versionSelect").value; currentIndex = 0; responses = {}; latest = null; stage = "assessment";
  $("setup").hidden = true; $("assessment").hidden = false; $("submitted").hidden = true;
  render(); toTop();
}
function next(){
  if(currentIndex < 19){ currentIndex++; render(); toTop(); return; }
  submit();
}

function buildSubmission(){
  const rows = QUESTION_BANK[num()], open = fmt() === "O";
  return {
    assessment: "IICS Technical Assessment",
    candidate, format: FORMAT_LABEL[fmt()], version: Number(num()), versionId: version,
    submissionId: crypto.randomUUID(), submittedAt: new Date().toISOString(),
    answers: rows.map((r, i) => {
      const a = responses[`${version}-${i}`];
      return open
        ? { number: i + 1, difficulty: r.level, topic: r.topic, question: r.open, response: a || "" }
        : { number: i + 1, difficulty: r.level, topic: r.topic, question: r.mcq, options: r.options,
            selectedOption: a === undefined ? null : a,
            selectedText: a === undefined ? "" : r.options[a] };
    })
  };
}
function toText(s){
  const lines = [s.assessment, `Candidate: ${s.candidate}`, `Format: ${s.format} · Version ${s.version}`,
    `Submitted: ${s.submittedAt}`, `Submission ID: ${s.submissionId}`, ""];
  s.answers.forEach(a => {
    lines.push(`Q${a.number} [${a.difficulty} · ${a.topic}]`, a.question);
    if(a.options){
      a.options.forEach((o, i) => lines.push(`  ${String.fromCharCode(65 + i)}. ${o}`));
      lines.push(a.selectedOption === null ? "ANSWER: (no answer)" : `ANSWER: ${String.fromCharCode(65 + a.selectedOption)}. ${a.selectedText}`);
    } else lines.push("ANSWER: " + (a.response || "(no answer)"));
    lines.push("");
  });
  return lines.join("\n");
}

function save(name, text, type){
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = Object.assign(document.createElement("a"), { href: url, download: name });
  document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
const baseName = () => `IICS_${fmt() === "O" ? "Open" : "MC"}_V${num()}_${safe(candidate)}`;
const saveJson = () => save(baseName() + ".json", JSON.stringify(latest.json, null, 2), "application/json");
const saveTxt = () => save(baseName() + ".txt", latest.txt, "text/plain");

function showSubmitted(){
  $("setup").hidden = true; $("assessment").hidden = true; $("submitted").hidden = false;
  $("submissionSummary").replaceChildren();
  const b = document.createElement("strong"); b.textContent = candidate;
  const s = document.createElement("span"); s.textContent = `${vLabel()} · 20 responses included.`;
  $("submissionSummary").append(b, s);
}
function submit(){
  latest = { json: buildSubmission() }; latest.txt = toText(latest.json);
  stage = "submitted"; persist(); showSubmitted();
  saveJson(); saveTxt(); toTop();
}
function restart(){
  const msg = stage === "submitted"
    ? "Go back to the start? Your downloaded files stay on your computer, but the answers saved here will be cleared."
    : "Go back to the start? Your answers so far will be erased.";
  if(!confirm(msg)) return;
  clearSaved(); responses = {}; latest = null; currentIndex = 0; candidate = ""; stage = "setup";
  $("candidateName").value = "";
  $("assessment").hidden = true; $("submitted").hidden = true; $("setup").hidden = false; toTop();
}
function restore(){
  let s; try{ s = JSON.parse(localStorage.getItem(STORE_KEY) || sessionStorage.getItem(STORE_KEY) || "null"); }catch{ s = null; }
  if(!s || !QUESTION_BANK[String(s.version || "").slice(1)] || !["assessment", "submitted"].includes(s.stage)) return;
  ({ candidate, version, responses, latest, stage } = s);
  currentIndex = Math.min(Math.max(Number(s.currentIndex) || 0, 0), 19);
  $("candidateName").value = candidate; $("versionSelect").value = version;
  if(stage === "submitted" && latest) showSubmitted();
  else { stage = "assessment"; $("setup").hidden = true; $("assessment").hidden = false; render(); }
}

$("startBtn").addEventListener("click", begin);
$("nextBtn").addEventListener("click", next);
$("backBtn").addEventListener("click", () => { currentIndex--; render(); toTop(); });
$("downloadJsonBtn").addEventListener("click", saveJson);
$("downloadTxtBtn").addEventListener("click", saveTxt);
document.querySelectorAll(".restart").forEach(b => b.addEventListener("click", restart));
window.addEventListener("pagehide", persist);
document.addEventListener("visibilitychange", () => { if(document.visibilityState === "hidden") persist(); });
restore();
